parameters.jsCode:
// Nœud n8n "Filtrer & préparer" (Code, runOnceForAllItems)
// Décode le corps des emails, applique les règles déterministes LinkedIn,
// extrait URL/Poste/Lieu/Mode pour les confirmations Envoyé, et construit
// le prompt Claude. Sortie : un item par email à classifier.
//
// Les alertes d'offres LinkedIn (jobalerts-noreply) ne sont plus ignorées :
// leur digest text/plain est découpé en cartes (une par offre) taguées
// kind:'veille'. Un Switch en aval ("Veille ?") sépare kind:'veille' du flux
// Candidatures (kind:'candidature'). Cf. veille-jobalerts.feature.md.

const items = $input.all();
const results = [];

const decodeB64 = (data) => {
  if (!data) return '';
  try { return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); }
  catch (e) { return ''; }
};

const extractText = (parts) => {
  if (!Array.isArray(parts)) return '';
  let text = '';
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) text += decodeB64(part.body.data) + ' ';
    else if (Array.isArray(part.parts)) text += extractText(part.parts);
  }
  return text;
};

// Lit un en-tête depuis le dict normalisé du nœud Gmail v2 (clés minuscules,
// valeurs de la forme "Nom: valeur").
const headerFromMap = (email, name) => {
  const h = email.headers;
  if (h && typeof h === 'object' && !Array.isArray(h)) {
    const raw = h[name.toLowerCase()];
    if (raw) return String(raw).replace(new RegExp('^\\s*' + name + '\\s*:\\s*', 'i'), '').trim();
  }
  return '';
};

// Récupère un en-tête quel que soit le format de sortie du nœud Gmail :
//  - brut (get full)            : email.payload.headers = [{name, value}]
//  - normalisé (node v2, simple:false) : champ direct minuscule (email.subject / email.date / …)
//    + dict email.headers {<nom-minuscule>: "Nom: valeur"}
// ⚠️ Le nœud "Gmail — Emails de la veille" renvoie la forme NORMALISÉE (pas de payload) :
// sans ce support, subject/from/date/domain remontaient tous vides (dates jamais écrites,
// règles LinkedIn forcées et filtrage jobalerts inopérants).
const getHeader = (email, name) => {
  const headers = email.payload?.headers;
  if (Array.isArray(headers)) {
    const found = headers.find(h => (h.name || '').toLowerCase() === name.toLowerCase());
    if (found) return found.value || '';
  }
  const low = name.toLowerCase();
  if (typeof email[low] === 'string' && email[low]) return email[low];
  const fromMap = headerFromMap(email, name);
  if (fromMap) return fromMap;
  const cap = name.charAt(0).toUpperCase() + name.slice(1);
  return email[name] || email[cap] || '';
};

const cutName = (s) => s.split(/\s[-|–—:]\s|\n|\bpour\b|\bfor\b/i)[0].trim().slice(0, 60);
const escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Normalise vers les valeurs FR utilisées dans Airtable Candidatures : "À distance" / "Hybride" / "Sur site"
const cleanMode = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};

// Trouve une URL d'offre LinkedIn dans un texte (HTML ou plain)
const findLinkedInJobUrl = (text) => {
  if (!text) return '';
  const m = String(text).match(/https?:\/\/(?:[\w.-]+\.)?linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
  return m ? `https://www.linkedin.com/jobs/view/${m[1]}/` : '';
};

// Cherche l'URL d'offre dans toutes les parties du payload (plain + html)
const findLinkedInJobUrlInPayload = (payload) => {
  if (!payload) return '';
  if (payload.body?.data) {
    const u = findLinkedInJobUrl(decodeB64(payload.body.data));
    if (u) return u;
  }
  if (Array.isArray(payload.parts)) {
    for (const p of payload.parts) {
      const u = findLinkedInJobUrlInPayload(p);
      if (u) return u;
    }
  }
  return '';
};

// --- Parseur de digest d'alertes emploi LinkedIn (jobalerts-noreply) ---
// Le corps text/plain liste les offres en blocs séparés par des lignes de tirets :
//   <Poste> / <Employeur> / <Lieu> / [badge…] / "Voir l'offre d'emploi : <URL …/jobs/view/JOBID/…>"
// Validé sur emails réels (2026-06-16). Pas de description du poste dans l'email
// (contrainte fiche) → on n'extrait que titre/employeur/lieu/mode + jobId/URL.
// Renvoie une carte par jobId (dédup intra-email ; dédup inter-jours = upsert Airtable).
const VEILLE_BADGES = /^(Top candidat|Croissance rapide|Recrutement actif|Cette entreprise recrute activement|Soyez parmi les premiers|Postulez avec|Candidature simplifiée|Easy Apply|Reprend contact|Forte affinité|Promu|En vedette|Actively recruiting|Be an early applicant|Top applicant|Salaire\b|\d+\s+relation)/i;

const parseJobAlertDigest = (plain) => {
  const cards = [];
  if (!plain) return cards;
  const seen = new Set();
  // Nom de l'alerte (recherche LinkedIn enregistrée) — contexte utile au triage
  const alertM = plain.match(/Votre alerte Emploi pour\s+(.+)/i);
  const alertName = alertM ? alertM[1].trim().slice(0, 200) : '';
  const blocks = plain.split(/\n[ \t]*-{3,}[ \t]*\n/);
  for (const block of blocks) {
    const jm = block.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
    if (!jm) continue;                       // en-tête / pied de page sans offre
    const jobId = jm[1];
    if (seen.has(jobId)) continue;           // dédup intra-email
    seen.add(jobId);
    const url = `https://www.linkedin.com/jobs/view/${jobId}/`;
    const rawLines = block.split('\n')
      .map(l => l.replace(/\s+/g, ' ').trim())
      .filter(Boolean);
    const easyApply = rawLines.some(l => /candidature simplifi\u00e9e|easy apply/i.test(l));
    const lines = rawLines
      .filter(l => !/^Votre alerte Emploi pour/i.test(l))
      .filter(l => !/^Voir l.offre d.emploi\s*:/i.test(l))
      .filter(l => !VEILLE_BADGES.test(l));
    const poste = (lines[0] || '').slice(0, 200);
    const employeur = (lines[1] || '').slice(0, 120);
    let lieu = (lines[2] || '').slice(0, 120);
    // Mode parfois accolé au lieu : "France (à distance)", "Paris (Hybride)"
    let mode = '';
    const lp = lieu.match(/^(.*?)\s*\(([^)]+)\)\s*$/);
    if (lp) { const m = cleanMode(lp[2]); if (m) { mode = m; lieu = lp[1].trim(); } }
    if (!mode) mode = cleanMode(lieu);
    cards.push({ jobId, url, employeur, poste, lieu, mode, alertName, easyApply });
  }
  return cards;
};

for (const item of items) {
  const email = item.json;

  const subject = getHeader(email, 'Subject');
  // From : objet normalisé {value:[{address,name}]} (node v2) OU en-tête brut.
  const fromObj = email.from;
  let fromRaw = '';
  if (fromObj && typeof fromObj === 'object' && Array.isArray(fromObj.value) && fromObj.value[0]) {
    const v = fromObj.value[0];
    fromRaw = v.name ? `${v.name} <${v.address || ''}>` : (v.address || '');
  } else {
    fromRaw = getHeader(email, 'From');
  }
  const dateRaw = getHeader(email, 'Date'); // node v2 : déjà ISO (ex. 2026-06-15T22:09:30.000Z)
  const fromEmail = (
    (fromObj && typeof fromObj === 'object' && fromObj.value && fromObj.value[0] && fromObj.value[0].address)
    || (fromRaw.match(/<([^>]+)>/) || [])[1]
    || fromRaw.trim()
    || ''
  ).toLowerCase();
  const domain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';
  const snippet = email.snippet
    || (typeof email.text === 'string' ? email.text.replace(/\s+/g, ' ').trim().slice(0, 400) : '');
  const isLinkedIn = domain.includes('linkedin.com');

  // Règles déterministes LinkedIn (sur sujet + aperçu)
  let forcedReponse = null;
  let forcedSociete = null;
  if (isLinkedIn) {
    const head = `${subject}\n${snippet}`;
    let m;
    if ((m = head.match(/your application was sent to\s+(.+)/i)) ||
        (m = head.match(/votre candidature a été envoyée à\s+(.+)/i)) ||
        (m = head.match(/candidature(?:\s+a(?:\s+bien)?\s+été)?\s+envoyée\s+à\s+(.+)/i))) {
      forcedReponse = 'Envoyé'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/your application was viewed by\s+(.+)/i)) ||
               (m = head.match(/candidature a été consultée par\s+(.+)/i))) {
      forcedReponse = 'A/R'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/derni[eè]re nouvelle de\s+(.+)/i))) {
      forcedReponse = 'Non'; forcedSociete = cutName(m[1]);
    }
  }

  // Alertes d'offres LinkedIn -> branche Veille (parse du digest en cartes)
  if (!forcedReponse && fromEmail === 'jobalerts-noreply@linkedin.com') {
    let plain = '';
    if (email.payload && Array.isArray(email.payload.parts)) plain = extractText(email.payload.parts);
    else if (email.payload?.body?.data) plain = decodeB64(email.payload.body.data);
    if (!plain) plain = email.plaintextBody || email.text || '';
    for (const c of parseJobAlertDigest(plain)) {
      results.push({
        json: {
          kind: 'veille',
          jobId: c.jobId, url: c.url,
          employeur: c.employeur, poste: c.poste, lieu: c.lieu, mode: c.mode,
          alertName: c.alertName, easyApply: c.easyApply || false,
          emailId: email.id || '', date: dateRaw,
        },
      });
    }
    continue; // ne pas envoyer ces emails dans le flux Candidatures
  }

  let bodyRaw = '';
  if (email.payload) {
    if (Array.isArray(email.payload.parts)) bodyRaw = extractText(email.payload.parts);
    else if (email.payload.body?.data) bodyRaw = decodeB64(email.payload.body.data);
  }
  if (!bodyRaw) bodyRaw = email.text || email.html || snippet || '';

  let bodyClean = String(bodyRaw).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (bodyClean.length > 2500) bodyClean = bodyClean.slice(0, 1800) + ' […] ' + bodyClean.slice(-700);

  // Enrichissement LinkedIn (Envoyé uniquement) — URL / Poste / Lieu / Mode
  let forcedUrl = '';
  let forcedPoste = null;
  let forcedLieu = null;
  let forcedMode = null;
  if (isLinkedIn && forcedReponse === 'Envoyé' && forcedSociete) {
    forcedUrl = findLinkedInJobUrlInPayload(email.payload);

    // Pattern : "<Société> <Poste> <Société> · <Lieu> (<Mode>?) ... Candidature/Application/Voir/View"
    const escSoc = escRe(forcedSociete);
    const stop = '(?:\\s+Candidature\\s+envoyée|\\s+Application\\s+sent|\\s+View\\s+job|\\s+Voir\\s+l|\\s+Postuler|$)';
    const re = new RegExp(
      `${escSoc}\\s+([^·•]+?)\\s+${escSoc}\\s*[·•]\\s*([^·•]+?)${stop}`,
      'i'
    );
    const mm = bodyClean.match(re);
    if (mm) {
      forcedPoste = mm[1].trim().slice(0, 200);
      const meta = mm[2].trim();
      const lm = meta.match(/^(.+?)\s*(?:\(([^)]+)\))?\s*$/);
      if (lm) {
        forcedLieu = lm[1].trim().slice(0, 100);
        forcedMode = cleanMode(lm[2] || meta);
      }
    }
  }

  const customId = ('m_' + (email.id || String(results.length)))
    .replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64);

  const claudePrompt = `Analyse cet email de candidature à l'emploi (en français) et classe la réponse de l'employeur.

Expéditeur : ${fromRaw}
Domaine expéditeur : ${domain}
Sujet : ${subject}
Corps : ${bodyClean || snippet}

Réponds UNIQUEMENT avec ce JSON, sans texte ni balises autour :
{"recrutement": true/false, "societe": "... ou null", "poste": "... ou null", "reponse": "A/R|Oui|Non", "confidence": "high|medium|low", "note": "1 phrase"}

DÉFINITIONS
- recrutement=true : email lié à une candidature précise (accusé de réception d'ATS, refus, invitation entretien, message d'un recruteur sur une candidature).
- recrutement=false : alertes/offres non sollicitées, newsletters ; emails d'AUTHENTIFICATION / code de connexion / vérification ; emails de BIENVENUE / création de compte / inscription à une plateforme ; invitations à une CONFÉRENCE / webinaire / événement (≠ entretien d'embauche) ; notifs bancaires, factures, pub, réseaux sociaux.
- societe : l'ENTREPRISE qui recrute. Si elle n'est pas explicite, DÉDUIS-LA de la signature, de l'adresse postale, du logo/nom cité dans le corps, ou du domaine de l'expéditeur. Jamais la plateforme/ATS ni le cabinet (ignorer Welcome to the Jungle, Greenhouse, Lever, Workday, LinkedIn). null seulement si vraiment introuvable.
- poste : déduis l'intitulé depuis le sujet, le corps ou la signature. null si introuvable.

CLASSEMENT DE reponse — lis le CORPS, pas seulement l'objet :
- "A/R" = accusé de réception, AUCUNE décision : « bien reçu votre candidature », « candidature enregistrée », « merci pour votre candidature », confirmation automatique.
- "Non" = refus : « ne donnerons pas suite », « profil n'a pas été retenu », « malheureusement », « regret », « unfortunately ».
- "Oui" = suite positive RÉELLE : invitation entretien/échange/appel/visio, test ou screening de sélection, « souhaitons vous rencontrer », « vos disponibilités », « prochaine étape ». PAS une invitation à une conférence/événement ni une simple inscription.

RÈGLES
- Un accusé de réception n'est PAS un refus. A/R ≠ Non ≠ Oui.
- En cas de doute entre les trois (si c'est bien du recrutement) → "A/R".`;

  results.push({
    json: {
      kind: 'candidature',
      customId, emailId: email.id || '', subject, fromRaw, fromEmail,
      date: dateRaw, domain, snippet, bodyClean, claudePrompt,
      forcedReponse, forcedSociete, forcedUrl, forcedPoste, forcedLieu, forcedMode,
    },
  });
}

return results;

// Nœud "Matcher & décider" (Code, runOnceForAllItems) — JACK : MàJ Candidatures.
// (27/06/2026) Réécrit pour s'alimenter de BOB ("Parser Triage BOB") au lieu du
// Batch Claude : BOB devient le classifieur unique. Mappe la catégorie BOB ->
// statut Réponse, conserve les règles déterministes LinkedIn (Envoyé/A-R/Non) de
// "Filtrer & préparer", rapproche chaque email d'une candidature existante et
// décide create / update / skip / review.
// $input = liste Candidatures ("Lister enregistrements"). BOB + métadonnées lus par référence.

const DENY = new Set(['indigoneo']);
const RANK = { '': 0, 'neant': 0, 'envoye': 1, 'a/r': 2, 'ar': 2, 'oui': 3, 'non': 3 };
const rankOf = (rp) => RANK[String(rp || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')] ?? 0;
const toIso = (s) => { if (!s) return ''; const dt = new Date(s); return isNaN(dt.getTime()) ? '' : dt.toISOString().slice(0, 10); };
const normalize = (s) => String(s || '')
  .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/\b(sas|sasu|sa|sarl|inc|ltd|llc|gmbh|group|groupe|technologies|tech|recruitment|recrutement|staffing)\b/g, '')
  .replace(/[^a-z0-9]/g, '');
const getField = (f, name) => {
  if (!f) return '';
  if (f[name] != null) return f[name];
  const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const target = norm(name);
  for (const k of Object.keys(f)) if (norm(k) === target) return f[k];
  return '';
};

const indexed = $input.all().map((i) => {
  const f = i.json.fields || i.json;
  return { id: getField(f, 'id') || i.json.id, societe: getField(f, 'societe'),
           poste: getField(f, 'poste'), reponse: getField(f, 'reponse'),
           key: normalize(getField(f, 'societe')) };
});

const findMatch = (societe, meta) => {
  const keyS = normalize(societe);
  if (keyS.length > 1) {
    const m = indexed.find(r => r.key && (r.key === keyS || r.key.includes(keyS) || keyS.includes(r.key)));
    if (m) return m;
  }
  const hay = normalize(`${meta.subject || ''} ${meta.snippet || ''} ${meta.bodyClean || ''} ${meta.fromRaw || ''}`);
  if (hay) {
    const hits = indexed.filter(r => r.key && r.key.length >= 4 && hay.includes(r.key)).sort((a, b) => b.key.length - a.key.length);
    if (hits.length) return hits[0];
  }
  const keyD = normalize((meta.domain || '').split('.')[0]);
  if (keyD.length > 2) {
    const m = indexed.find(r => r.key && (r.key.includes(keyD) || keyD.includes(r.key)));
    if (m) return m;
  }
  return null;
};

// Catégorie BOB -> {recrutement, statut Réponse}. (id_email 'li-...' = veille -> ignoré.)
const CAT = {
  'Accusé de réception':    { rec: true, reponse: 'A/R' },
  'Réponse positive':       { rec: true, reponse: 'Oui' },
  'Refus':                  { rec: true, reponse: 'Non' },
  'Proposition de mission': { rec: false },
  'Autre/non-pertinent':    { rec: false },
};
const bobByEmail = {};
for (const it of $('Parser Triage BOB').all()) {
  const j = it.json || {};
  if (j.id_email && !String(j.id_email).startsWith('li-')) bobByEmail[j.id_email] = j;
}

const out = [];
for (const it of $('Filtrer & préparer').all()) {
  const meta = it.json;
  if (meta.kind !== 'candidature') continue;
  const bob = bobByEmail[meta.emailId] || {};
  const cat = CAT[bob.categorie] || { rec: false };
  const forced = !!meta.forcedReponse;
  if (!forced && cat.rec !== true) continue;

  let societe, societeReliable;
  if (meta.forcedSociete) { societe = meta.forcedSociete; societeReliable = true; }
  else if (bob.societe && bob.societe !== '') { societe = bob.societe; societeReliable = true; }
  else { societe = meta.domain ? meta.domain.split('.')[0] : ''; societeReliable = false; }

  const poste = meta.forcedPoste || (bob.poste || '');
  const lieu = meta.forcedLieu || '';
  const mode = meta.forcedMode || '';
  const linkedinUrl = meta.forcedUrl || '';
  const reponse = forced ? meta.forcedReponse : (cat.reponse || 'A/R');

  if (DENY.has(normalize(societe))) continue;
  const match = findMatch(societe, meta);

  let action, airtableId = null;
  if (match) { airtableId = match.id; action = rankOf(reponse) > rankOf(match.reponse) ? 'update' : 'skip'; }
  else if (societeReliable && normalize(societe).length >= 2) { action = 'create'; }
  else { action = 'review'; }

  out.push({ json: {
    action, airtableId, societe, poste, reponse, lieu, mode, linkedinUrl,
    subject: meta.subject, fromRaw: meta.fromRaw, date: toIso(meta.date),
    note: bob.justification || '',
    gmailLink: meta.emailId ? `https://mail.google.com/mail/u/0/#all/${meta.emailId}` : '',
    domain: meta.domain, emailId: meta.emailId,
    confidence: bob.confiance || 'low',
    forced, existingReponse: match ? match.reponse : null,
  }});
}

const best = new Map();
const reviews = [];
for (const o of out) {
  if (o.json.action === 'review') { reviews.push(o); continue; }
  const k = (o.json.action === 'create') ? ('soc:' + normalize(o.json.societe)) : ('id:' + o.json.airtableId);
  const prev = best.get(k);
  if (!prev || rankOf(o.json.reponse) > rankOf(prev.json.reponse)) best.set(k, o);
}
return [...best.values(), ...reviews];

// Nœud "Prépa triage Veille" (Code, runOnceForAllItems)
// (Étage de triage grossier supprimé le 27/06/2026 — le scoring précis le remplace.)
// Collecte les cartes d'offres veille du jour ; la dédup + le shaping se font
// dans "Parser triage Veille". Sort un unique item { cards }.
const cards = $input.all().map((it) => it.json);
return [{ json: { cards, count: cards.length } }];

// Nœud "Parser triage Veille" (Code, runOnceForAllItems)
// (Étage de triage grossier supprimé le 27/06/2026.) Déduplique les offres par jobId
// (même offre vue dans plusieurs alertes le même jour) et formate chaque carte
// pour l'écriture Airtable. Plus d'appel Claude de pré-classement ni de champs de triage.
const src = $('Prépa triage Veille').first().json;
const cards = src.cards || [];
const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };
const seen = new Set();
const out = [];
for (const c of cards) {
  if (c.jobId && seen.has(c.jobId)) continue;
  if (c.jobId) seen.add(c.jobId);
  out.push({ json: {
    jobId: c.jobId, employeur: c.employeur, poste: c.poste, lieu: c.lieu,
    mode: c.mode, url: c.url, alertName: c.alertName, date: toIso(c.date),
    easyApply: c.easyApply || false,
  }});
}
return out;

// Nœud n8n "Veille décider" (Code, runOnceForAllItems)
// Décide create vs update pour chaque carte, SANS dépendre du pairedItem.
const existing = {};
for (const it of $('Chercher Veille').all()) {
  const j = it.json || {};
  if (j.id && j.jobId != null) existing[String(j.jobId)] = j.id;
}
// Garde-fou : offres déjà recopiées dans Candidatures ("Je postule") -> ne pas recréer
// dans la veille si une future alerte les fait réapparaître (jobId extrait de l'URL).
const applied = new Set();
for (const it of $('Lister Candidatures (URL)').all()) {
  const j = it.json || {};
  const url = j.URL || j.url || '';
  const m = String(url).match(/jobs\/view\/(\d+)/i);
  if (m) applied.add(m[1]);
}

return $('Parser triage Veille').all()
  .map((it) => it.json)
  .filter((c) => !(c.jobId && applied.has(String(c.jobId))))
  .map((c) => {
    const airtableId = existing[String(c.jobId)] || null;
    return { json: { ...c, action: airtableId ? 'update' : 'create', airtableId } };
  });

// Nœud "Filtrer à enrichir" (Code, runOnceForAllItems)
// (Pré-filtre grossier supprimé le 27/06/2026 : on score TOUTES les offres.)
// On enrichit toute offre pas encore notée (Note rôle vide).
return $input.all()
  .map(it => it.json)
  .filter(r => {
    const note = r['Note rôle'];
    return !(note && String(note).trim());
  })
  .map(r => ({ json: {
    id: r.id, jobId: r.jobId, poste: r.Poste, employeur: r.Employeur,
    lieu: r.Lieu, url: r.URL,
    easyApplyFromAirtable: r['Easy Apply'] || false
  }}));

const rec = $('Filtrer à enrichir').item.json;
const html = ($json && ($json.data || $json.body)) || '';
const clean = s => s
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim();
let desc = '';
const i = html.indexOf('show-more-less-html__markup');
if (i >= 0) {
  let chunk = html.slice(i, i + 14000).replace(/show-more-less-html__markup[^>]*>/, '');
  const cut = chunk.search(/show-more-less__button|<\/section>/);
  if (cut > 0) chunk = chunk.slice(0, cut);
  desc = clean(chunk);
}
const crit = [];
const re = /job-criteria-subheader[^>]*>([\s\S]*?)<\/h3>[\s\S]*?job-criteria-text[^>]*>([\s\S]*?)<\/span>/g;
let m;
while ((m = re.exec(html))) crit.push(clean(m[1]) + ': ' + clean(m[2]));

// Extract mode from criteria (e.g. "Télétravail: À distance")
const cleanModeLocal = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};
let modeFromJd = '';
for (const c of crit) {
  if (/télétravail|remote|workplace|travail.à.distance/i.test(c)) {
    const parts = c.split(':');
    if (parts.length > 1) modeFromJd = cleanModeLocal(parts.slice(1).join(':'));
    break;
  }
}
// Detect Easy Apply from page HTML
// Easy Apply: detect in JD HTML OR fallback on jobalert value already in Airtable
const easyApply = /candidature simplifi\u00e9e|easy apply/i.test(html) || !!rec.easyApplyFromAirtable;
return { json: { ...rec, descText: desc, criteres: crit.join(' | '), ok: desc.length > 200, modeFromJd, easyApply } };

const PROFIL = `Profil candidat : consultant senior independant, 25 ans d'experience, 100% assurance & finance. Cherche mission freelance/contract/interim (CDI senior finance possible), full remote ou hybride privilegie, TJM >= 800 EUR/j. Ouvert a l'international en remote (EMEA, Amerique du Nord, APAC).`;
const r = $json;
const prompt = `${PROFIL}

Voici une offre d'emploi. Redige DEUX notes courtes en francais, factuelles, pour aider ce candidat a decider de postuler.

OFFRE : ${r.poste} — ${r.employeur} — ${r.lieu || 'lieu n.c.'}
CRITERES LINKEDIN : ${r.criteres || 'n.c.'}
DESCRIPTION :
${(r.descText || '').slice(0, 6000)}

Reponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"note_role":"3 a 5 phrases : de quoi parle le poste, missions cles, seniorite, et en quoi il matche ou non le profil sur le FOND du role","note_criteres":"3 a 5 puces separees par des retours a la ligne, chaque ligne prefixee '- ' : pour chaque critere cle du recruteur (seniorite, type de contrat, secteur, competences, langue, localisation/remote) indique match ou ecart vs le profil","mode":"valeur parmi : A distance, Hybride, Sur site — ou null si non mentionne dans l offre"}`;
return { json: { prompt, id: r.id, jobId: r.jobId, modeFromJd: r.modeFromJd || '', easyApply: !!r.easyApply } };

const rec = $('Prépa prompt notes').item.json;
let role = '', crit = '', modeFromNotes = '';
try {
  const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { const o = JSON.parse(m[0]); role = o.note_role || ''; crit = o.note_criteres || ''; modeFromNotes = o.mode || ''; }
} catch (e) { /* laisse vide -> retente au prochain run */ }
if (!role && !crit) return null;
return { json: { id: rec.id, noteRole: role, noteCriteres: crit, modeFromNotes, modeFromJd: rec.modeFromJd || '', easyApply: !!rec.easyApply } };

// Parser score — extrait JSON de la réponse Claude
const upstream = $('Prépa prompt scoring').item.json;
const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';

let score = null, signaux = [], justification = '';
try {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) {
    const o = JSON.parse(m[0]);
    const raw = typeof o.score === 'number' ? o.score : parseInt(o.score, 10);
    score = isNaN(raw) ? null : Math.min(100, Math.max(0, raw));
    signaux = Array.isArray(o.signaux) ? o.signaux : [];
    justification = o.justification || '';
  }
} catch (e) { /* score reste null, sera ignoré par Écrire notes */ }

return { json: {
  id: upstream.id,
  noteRole: upstream.noteRole,
  noteCriteres: upstream.noteCriteres,
  modeFromNotes: upstream.modeFromNotes || '',
  modeFromJd: upstream.modeFromJd || '',
  // Préparer dossier = règle Score >= 35 (remplace l ancien pré-classement grossier, 27/06/2026).
  // score null (scoring échoué/crédits) -> pas de préparation auto (fail-safe).
  preparer: (score !== null && score >= 35),
  postule: (score !== null && score >= 35 && !!upstream.easyApply),
  easyApply: !!upstream.easyApply,
  score,
  scoreSignaux: signaux.join(' | '),
  scoreJustification: justification
}};

// Nœud "Prépa Triage BOB" (Code, runOnceForAllItems)
// Port n8n de l'agent BOB (triage 5 catégories). Reçoit TOUTE la sortie de
// "Filtrer & préparer" (kind:'veille' + kind:'candidature'). Les offres LinkedIn
// (veille) sont pré-classées "Proposition de mission" sans LLM. Les emails de
// candidature sont regroupés en UN seul prompt (1 appel Claude pour tous, comme
// l'agent BOB d'origine et comme "Prépa triage Veille") -> robuste au rate-limit.
// Sort un unique item { prompt, candEmails, veilleRecords } consommé par l'appel
// Claude puis par "Parser Triage BOB".

const all = $input.all().map((it) => it.json);
if (all.length === 0) return [];

const veilleRecords = [];
const candEmails = [];
for (const it of all) {
  if (it.kind === 'veille') {
    veilleRecords.push({
      id_email: 'li-' + (it.jobId || ''),
      sujet: it.poste || '',
      expediteur: it.employeur || '',
      categorie: 'Proposition de mission',
      societe: it.employeur || '',
      poste: it.poste || '',
      confiance: 'Haute',
      justification: 'Offre diffusée par une alerte LinkedIn' + (it.alertName ? ' (' + it.alertName + ')' : '') + '.',
      lieu: it.lieu || '',
      url: it.url || '',
      mode: it.mode || '',
    });
  } else {
    candEmails.push({
      id_email: it.emailId || it.customId || '',
      emailUrl: it.emailId ? 'https://mail.google.com/mail/u/0/#all/' + it.emailId : '',
      sujet: it.subject || '',
      expediteur: it.fromRaw || '',
      bodyClean: it.bodyClean || it.snippet || '',
    });
  }
}

const SYSTEM = `Tu es BOB, l'agent de Xavier Robitaille. Ton rôle : trier les emails liés à sa recherche de mission de conseil.
Pour CHAQUE email, attribue EXACTEMENT UNE catégorie :
- "Proposition de mission" : un recruteur/client propose une mission ou un poste précis.
- "Accusé de réception" : confirmation (souvent automatique) qu'une candidature a bien été reçue/envoyée, SANS décision.
- "Réponse positive" : intérêt, demande d'entretien/échange/disponibilités, suite favorable.
- "Refus" : candidature non retenue (« ne donnerons pas suite », « pas retenu », « unfortunately »).
- "Autre/non-pertinent" : newsletter, alerte non sollicitée, authentification/code, bienvenue/création de compte, invitation à une conférence/webinaire, notif bancaire, spam — tout ce qui n'est pas lié à une candidature précise.
Extrais la société (l'entreprise qui recrute, jamais l'ATS/plateforme : ignore LinkedIn, Welcome to the Jungle, Greenhouse, Lever, Workday) et le poste quand ils sont identifiables, sinon laisse vide.
Un accusé de réception n'est ni un refus ni une réponse positive. En cas de doute entre les trois (si c'est bien du recrutement) → "Accusé de réception".`;

const lignes = candEmails.map((e, i) =>
  `### Email ${i + 1}\nExpéditeur : ${e.expediteur}\nSujet : ${e.sujet}\nCorps : ${String(e.bodyClean || '').slice(0, 1500)}`
).join('\n\n');

const prompt = `${SYSTEM}\n\nClasse CHAQUE email ci-dessous. Réponds UNIQUEMENT par un tableau JSON, un objet par email DANS L'ORDRE, sans aucun texte autour :\n[{"i":1,"categorie":"Proposition de mission|Accusé de réception|Réponse positive|Refus|Autre/non-pertinent","societe":"... ou ''","poste":"... ou ''","confiance":"Haute|Moyenne|Basse","justification":"<=1 phrase en français"}]\n\nEMAILS :\n${lignes}`;

return [{ json: { prompt, candEmails, veilleRecords, candCount: candEmails.length } }];

// Nœud "Parser Triage BOB" (Code, runOnceForAllItems)
// Rattache la classification Claude à chaque email de candidature (par index),
// tolérant à une réponse tronquée. Y ajoute les offres veille pré-classées.
// Si l'appel Claude a échoué (onError:continueRegularOutput -> pas de .content),
// on N'ÉCRIT PAS les candidatures (évite de tout classer "Autre") : seules les
// offres veille sont écrites, les candidatures repasseront au run suivant
// (fenêtre 24h glissante).

const src = $('Prépa Triage BOB').first().json;
const candEmails = src.candEmails || [];
const veilleRecords = src.veilleRecords || [];

const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
const claudeOk = !!txt;

const byI = {};
const objs = txt.match(/\{[^{}]*\}/g) || [];
for (const frag of objs) {
  try { const o = JSON.parse(frag); if (o && o.i != null) byI[Number(o.i)] = o; } catch (e) {}
}

const validCat = ['Proposition de mission', 'Accusé de réception', 'Réponse positive', 'Refus', 'Autre/non-pertinent'];
const validConf = ['Haute', 'Moyenne', 'Basse'];

const out = [];
for (const v of veilleRecords) out.push({ json: v });

if (claudeOk) {
  candEmails.forEach((e, idx) => {
    const o = byI[idx + 1];
    if (!o) return; // pas de classif (réponse tronquée) -> réécrit au prochain run
    const categorie = validCat.includes(o.categorie) ? o.categorie : 'Autre/non-pertinent';
    const confiance = validConf.includes(o.confiance) ? o.confiance : 'Basse';
    out.push({ json: {
      id_email: e.id_email,
      sujet: e.sujet,
      expediteur: e.expediteur,
      categorie,
      societe: o.societe || '',
      poste: o.poste || '',
      confiance,
      justification: o.justification || '',
      lieu: '', url: '', mode: '',
      emailUrl: e.emailUrl || '',
    }});
  });
}

return out;

// Nœud n8n "Filtrer & préparer" (Code, runOnceForAllItems)
// Décode le corps des emails, applique les règles déterministes LinkedIn,
// extrait URL/Poste/Lieu/Mode pour les confirmations Envoyé, et construit
// le prompt Claude. Sortie : un item par email à classifier.
//
// Les alertes d'offres LinkedIn (jobalerts-noreply) ne sont plus ignorées :
// leur digest text/plain est découpé en cartes (une par offre) taguées
// kind:'veille'. Un Switch en aval ("Veille ?") sépare kind:'veille' du flux
// Candidatures (kind:'candidature'). Cf. veille-jobalerts.feature.md.

const items = $input.all();
const results = [];

const decodeB64 = (data) => {
  if (!data) return '';
  try { return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); }
  catch (e) { return ''; }
};

const extractText = (parts) => {
  if (!Array.isArray(parts)) return '';
  let text = '';
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) text += decodeB64(part.body.data) + ' ';
    else if (Array.isArray(part.parts)) text += extractText(part.parts);
  }
  return text;
};

// Lit un en-tête depuis le dict normalisé du nœud Gmail v2 (clés minuscules,
// valeurs de la forme "Nom: valeur").
const headerFromMap = (email, name) => {
  const h = email.headers;
  if (h && typeof h === 'object' && !Array.isArray(h)) {
    const raw = h[name.toLowerCase()];
    if (raw) return String(raw).replace(new RegExp('^\\s*' + name + '\\s*:\\s*', 'i'), '').trim();
  }
  return '';
};

// Récupère un en-tête quel que soit le format de sortie du nœud Gmail :
//  - brut (get full)            : email.payload.headers = [{name, value}]
//  - normalisé (node v2, simple:false) : champ direct minuscule (email.subject / email.date / …)
//    + dict email.headers {<nom-minuscule>: "Nom: valeur"}
// ⚠️ Le nœud "Gmail — Emails de la veille" renvoie la forme NORMALISÉE (pas de payload) :
// sans ce support, subject/from/date/domain remontaient tous vides (dates jamais écrites,
// règles LinkedIn forcées et filtrage jobalerts inopérants).
const getHeader = (email, name) => {
  const headers = email.payload?.headers;
  if (Array.isArray(headers)) {
    const found = headers.find(h => (h.name || '').toLowerCase() === name.toLowerCase());
    if (found) return found.value || '';
  }
  const low = name.toLowerCase();
  if (typeof email[low] === 'string' && email[low]) return email[low];
  const fromMap = headerFromMap(email, name);
  if (fromMap) return fromMap;
  const cap = name.charAt(0).toUpperCase() + name.slice(1);
  return email[name] || email[cap] || '';
};

const cutName = (s) => s.split(/\s[-|–—:]\s|\n|\bpour\b|\bfor\b/i)[0].trim().slice(0, 60);
const escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Normalise vers les valeurs FR utilisées dans Airtable Candidatures : "À distance" / "Hybride" / "Sur site"
const cleanMode = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};

// Trouve une URL d'offre LinkedIn dans un texte (HTML ou plain)
const findLinkedInJobUrl = (text) => {
  if (!text) return '';
  const m = String(text).match(/https?:\/\/(?:[\w.-]+\.)?linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
  return m ? `https://www.linkedin.com/jobs/view/${m[1]}/` : '';
};

// Cherche l'URL d'offre dans toutes les parties du payload (plain + html)
const findLinkedInJobUrlInPayload = (payload) => {
  if (!payload) return '';
  if (payload.body?.data) {
    const u = findLinkedInJobUrl(decodeB64(payload.body.data));
    if (u) return u;
  }
  if (Array.isArray(payload.parts)) {
    for (const p of payload.parts) {
      const u = findLinkedInJobUrlInPayload(p);
      if (u) return u;
    }
  }
  return '';
};

// --- Parseur de digest d'alertes emploi LinkedIn (jobalerts-noreply) ---
// Le corps text/plain liste les offres en blocs séparés par des lignes de tirets :
//   <Poste> / <Employeur> / <Lieu> / [badge…] / "Voir l'offre d'emploi : <URL …/jobs/view/JOBID/…>"
// Validé sur emails réels (2026-06-16). Pas de description du poste dans l'email
// (contrainte fiche) → on n'extrait que titre/employeur/lieu/mode + jobId/URL.
// Renvoie une carte par jobId (dédup intra-email ; dédup inter-jours = upsert Airtable).
const VEILLE_BADGES = /^(Top candidat|Croissance rapide|Recrutement actif|Cette entreprise recrute activement|Soyez parmi les premiers|Postulez avec|Candidature simplifiée|Easy Apply|Reprend contact|Forte affinité|Promu|En vedette|Actively recruiting|Be an early applicant|Top applicant|Salaire\b|\d+\s+relation)/i;

const parseJobAlertDigest = (plain) => {
  const cards = [];
  if (!plain) return cards;
  const seen = new Set();
  // Nom de l'alerte (recherche LinkedIn enregistrée) — contexte utile au triage
  const alertM = plain.match(/Votre alerte Emploi pour\s+(.+)/i);
  const alertName = alertM ? alertM[1].trim().slice(0, 200) : '';
  const blocks = plain.split(/\n[ \t]*-{3,}[ \t]*\n/);
  for (const block of blocks) {
    const jm = block.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
    if (!jm) continue;                       // en-tête / pied de page sans offre
    const jobId = jm[1];
    if (seen.has(jobId)) continue;           // dédup intra-email
    seen.add(jobId);
    const url = `https://www.linkedin.com/jobs/view/${jobId}/`;
    const rawLines = block.split('\n')
      .map(l => l.replace(/\s+/g, ' ').trim())
      .filter(Boolean);
    const easyApply = rawLines.some(l => /candidature simplifi\u00e9e|easy apply/i.test(l));
    const lines = rawLines
      .filter(l => !/^Votre alerte Emploi pour/i.test(l))
      .filter(l => !/^Voir l.offre d.emploi\s*:/i.test(l))
      .filter(l => !VEILLE_BADGES.test(l));
    const poste = (lines[0] || '').slice(0, 200);
    const employeur = (lines[1] || '').slice(0, 120);
    let lieu = (lines[2] || '').slice(0, 120);
    // Mode parfois accolé au lieu : "France (à distance)", "Paris (Hybride)"
    let mode = '';
    const lp = lieu.match(/^(.*?)\s*\(([^)]+)\)\s*$/);
    if (lp) { const m = cleanMode(lp[2]); if (m) { mode = m; lieu = lp[1].trim(); } }
    if (!mode) mode = cleanMode(lieu);
    cards.push({ jobId, url, employeur, poste, lieu, mode, alertName, easyApply });
  }
  return cards;
};

for (const item of items) {
  const email = item.json;

  const subject = getHeader(email, 'Subject');
  // From : objet normalisé {value:[{address,name}]} (node v2) OU en-tête brut.
  const fromObj = email.from;
  let fromRaw = '';
  if (fromObj && typeof fromObj === 'object' && Array.isArray(fromObj.value) && fromObj.value[0]) {
    const v = fromObj.value[0];
    fromRaw = v.name ? `${v.name} <${v.address || ''}>` : (v.address || '');
  } else {
    fromRaw = getHeader(email, 'From');
  }
  const dateRaw = getHeader(email, 'Date'); // node v2 : déjà ISO (ex. 2026-06-15T22:09:30.000Z)
  const fromEmail = (
    (fromObj && typeof fromObj === 'object' && fromObj.value && fromObj.value[0] && fromObj.value[0].address)
    || (fromRaw.match(/<([^>]+)>/) || [])[1]
    || fromRaw.trim()
    || ''
  ).toLowerCase();
  const domain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';
  const snippet = email.snippet
    || (typeof email.text === 'string' ? email.text.replace(/\s+/g, ' ').trim().slice(0, 400) : '');
  const isLinkedIn = domain.includes('linkedin.com');

  // Règles déterministes LinkedIn (sur sujet + aperçu)
  let forcedReponse = null;
  let forcedSociete = null;
  if (isLinkedIn) {
    const head = `${subject}\n${snippet}`;
    let m;
    if ((m = head.match(/your application was sent to\s+(.+)/i)) ||
        (m = head.match(/votre candidature a été envoyée à\s+(.+)/i)) ||
        (m = head.match(/candidature(?:\s+a(?:\s+bien)?\s+été)?\s+envoyée\s+à\s+(.+)/i))) {
      forcedReponse = 'Envoyé'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/your application was viewed by\s+(.+)/i)) ||
               (m = head.match(/candidature a été consultée par\s+(.+)/i))) {
      forcedReponse = 'A/R'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/derni[eè]re nouvelle de\s+(.+)/i))) {
      forcedReponse = 'Non'; forcedSociete = cutName(m[1]);
    }
  }

  // Alertes d'offres LinkedIn -> branche Veille (parse du digest en cartes)
  if (!forcedReponse && fromEmail === 'jobalerts-noreply@linkedin.com') {
    let plain = '';
    if (email.payload && Array.isArray(email.payload.parts)) plain = extractText(email.payload.parts);
    else if (email.payload?.body?.data) plain = decodeB64(email.payload.body.data);
    if (!plain) plain = email.plaintextBody || email.text || '';
    for (const c of parseJobAlertDigest(plain)) {
      results.push({
        json: {
          kind: 'veille',
          jobId: c.jobId, url: c.url,
          employeur: c.employeur, poste: c.poste, lieu: c.lieu, mode: c.mode,
          alertName: c.alertName, easyApply: c.easyApply || false,
          emailId: email.id || '', date: dateRaw,
        },
      });
    }
    continue; // ne pas envoyer ces emails dans le flux Candidatures
  }

  let bodyRaw = '';
  if (email.payload) {
    if (Array.isArray(email.payload.parts)) bodyRaw = extractText(email.payload.parts);
    else if (email.payload.body?.data) bodyRaw = decodeB64(email.payload.body.data);
  }
  if (!bodyRaw) bodyRaw = email.text || email.html || snippet || '';

  let bodyClean = String(bodyRaw).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (bodyClean.length > 2500) bodyClean = bodyClean.slice(0, 1800) + ' […] ' + bodyClean.slice(-700);

  // Enrichissement LinkedIn (Envoyé uniquement) — URL / Poste / Lieu / Mode
  let forcedUrl = '';
  let forcedPoste = null;
  let forcedLieu = null;
  let forcedMode = null;
  if (isLinkedIn && forcedReponse === 'Envoyé' && forcedSociete) {
    forcedUrl = findLinkedInJobUrlInPayload(email.payload);

    // Pattern : "<Société> <Poste> <Société> · <Lieu> (<Mode>?) ... Candidature/Application/Voir/View"
    const escSoc = escRe(forcedSociete);
    const stop = '(?:\\s+Candidature\\s+envoyée|\\s+Application\\s+sent|\\s+View\\s+job|\\s+Voir\\s+l|\\s+Postuler|$)';
    const re = new RegExp(
      `${escSoc}\\s+([^·•]+?)\\s+${escSoc}\\s*[·•]\\s*([^·•]+?)${stop}`,
      'i'
    );
    const mm = bodyClean.match(re);
    if (mm) {
      forcedPoste = mm[1].trim().slice(0, 200);
      const meta = mm[2].trim();
      const lm = meta.match(/^(.+?)\s*(?:\(([^)]+)\))?\s*$/);
      if (lm) {
        forcedLieu = lm[1].trim().slice(0, 100);
        forcedMode = cleanMode(lm[2] || meta);
      }
    }
  }

  const customId = ('m_' + (email.id || String(results.length)))
    .replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64);

  const claudePrompt = `Analyse cet email de candidature à l'emploi (en français) et classe la réponse de l'employeur.

Expéditeur : ${fromRaw}
Domaine expéditeur : ${domain}
Sujet : ${subject}
Corps : ${bodyClean || snippet}

Réponds UNIQUEMENT avec ce JSON, sans texte ni balises autour :
{"recrutement": true/false, "societe": "... ou null", "poste": "... ou null", "reponse": "A/R|Oui|Non", "confidence": "high|medium|low", "note": "1 phrase"}

DÉFINITIONS
- recrutement=true : email lié à une candidature précise (accusé de réception d'ATS, refus, invitation entretien, message d'un recruteur sur une candidature).
- recrutement=false : alertes/offres non sollicitées, newsletters ; emails d'AUTHENTIFICATION / code de connexion / vérification ; emails de BIENVENUE / création de compte / inscription à une plateforme ; invitations à une CONFÉRENCE / webinaire / événement (≠ entretien d'embauche) ; notifs bancaires, factures, pub, réseaux sociaux.
- societe : l'ENTREPRISE qui recrute. Si elle n'est pas explicite, DÉDUIS-LA de la signature, de l'adresse postale, du logo/nom cité dans le corps, ou du domaine de l'expéditeur. Jamais la plateforme/ATS ni le cabinet (ignorer Welcome to the Jungle, Greenhouse, Lever, Workday, LinkedIn). null seulement si vraiment introuvable.
- poste : déduis l'intitulé depuis le sujet, le corps ou la signature. null si introuvable.

CLASSEMENT DE reponse — lis le CORPS, pas seulement l'objet :
- "A/R" = accusé de réception, AUCUNE décision : « bien reçu votre candidature », « candidature enregistrée », « merci pour votre candidature », confirmation automatique.
- "Non" = refus : « ne donnerons pas suite », « profil n'a pas été retenu », « malheureusement », « regret », « unfortunately ».
- "Oui" = suite positive RÉELLE : invitation entretien/échange/appel/visio, test ou screening de sélection, « souhaitons vous rencontrer », « vos disponibilités », « prochaine étape ». PAS une invitation à une conférence/événement ni une simple inscription.

RÈGLES
- Un accusé de réception n'est PAS un refus. A/R ≠ Non ≠ Oui.
- En cas de doute entre les trois (si c'est bien du recrutement) → "A/R".`;

  results.push({
    json: {
      kind: 'candidature',
      customId, emailId: email.id || '', subject, fromRaw, fromEmail,
      date: dateRaw, domain, snippet, bodyClean, claudePrompt,
      forcedReponse, forcedSociete, forcedUrl, forcedPoste, forcedLieu, forcedMode,
    },
  });
}

return results;

// Nœud "Matcher & décider" (Code, runOnceForAllItems) — JACK : MàJ Candidatures.
// (27/06/2026) Réécrit pour s'alimenter de BOB ("Parser Triage BOB") au lieu du
// Batch Claude : BOB devient le classifieur unique. Mappe la catégorie BOB ->
// statut Réponse, conserve les règles déterministes LinkedIn (Envoyé/A-R/Non) de
// "Filtrer & préparer", rapproche chaque email d'une candidature existante et
// décide create / update / skip / review.
// $input = liste Candidatures ("Lister enregistrements"). BOB + métadonnées lus par référence.

const DENY = new Set(['indigoneo']);
const RANK = { '': 0, 'neant': 0, 'envoye': 1, 'a/r': 2, 'ar': 2, 'oui': 3, 'non': 3 };
const rankOf = (rp) => RANK[String(rp || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')] ?? 0;
const toIso = (s) => { if (!s) return ''; const dt = new Date(s); return isNaN(dt.getTime()) ? '' : dt.toISOString().slice(0, 10); };
const normalize = (s) => String(s || '')
  .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/\b(sas|sasu|sa|sarl|inc|ltd|llc|gmbh|group|groupe|technologies|tech|recruitment|recrutement|staffing)\b/g, '')
  .replace(/[^a-z0-9]/g, '');
const getField = (f, name) => {
  if (!f) return '';
  if (f[name] != null) return f[name];
  const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const target = norm(name);
  for (const k of Object.keys(f)) if (norm(k) === target) return f[k];
  return '';
};

const indexed = $input.all().map((i) => {
  const f = i.json.fields || i.json;
  return { id: getField(f, 'id') || i.json.id, societe: getField(f, 'societe'),
           poste: getField(f, 'poste'), reponse: getField(f, 'reponse'),
           key: normalize(getField(f, 'societe')) };
});

const findMatch = (societe, meta) => {
  const keyS = normalize(societe);
  if (keyS.length > 1) {
    const m = indexed.find(r => r.key && (r.key === keyS || r.key.includes(keyS) || keyS.includes(r.key)));
    if (m) return m;
  }
  const hay = normalize(`${meta.subject || ''} ${meta.snippet || ''} ${meta.bodyClean || ''} ${meta.fromRaw || ''}`);
  if (hay) {
    const hits = indexed.filter(r => r.key && r.key.length >= 4 && hay.includes(r.key)).sort((a, b) => b.key.length - a.key.length);
    if (hits.length) return hits[0];
  }
  const keyD = normalize((meta.domain || '').split('.')[0]);
  if (keyD.length > 2) {
    const m = indexed.find(r => r.key && (r.key.includes(keyD) || keyD.includes(r.key)));
    if (m) return m;
  }
  return null;
};

// Catégorie BOB -> {recrutement, statut Réponse}. (id_email 'li-...' = veille -> ignoré.)
const CAT = {
  'Accusé de réception':    { rec: true, reponse: 'A/R' },
  'Réponse positive':       { rec: true, reponse: 'Oui' },
  'Refus':                  { rec: true, reponse: 'Non' },
  'Proposition de mission': { rec: false },
  'Autre/non-pertinent':    { rec: false },
};
const bobByEmail = {};
for (const it of $('Parser Triage BOB').all()) {
  const j = it.json || {};
  if (j.id_email && !String(j.id_email).startsWith('li-')) bobByEmail[j.id_email] = j;
}

const out = [];
for (const it of $('Filtrer & préparer').all()) {
  const meta = it.json;
  if (meta.kind !== 'candidature') continue;
  const bob = bobByEmail[meta.emailId] || {};
  const cat = CAT[bob.categorie] || { rec: false };
  const forced = !!meta.forcedReponse;
  if (!forced && cat.rec !== true) continue;

  let societe, societeReliable;
  if (meta.forcedSociete) { societe = meta.forcedSociete; societeReliable = true; }
  else if (bob.societe && bob.societe !== '') { societe = bob.societe; societeReliable = true; }
  else { societe = meta.domain ? meta.domain.split('.')[0] : ''; societeReliable = false; }

  const poste = meta.forcedPoste || (bob.poste || '');
  const lieu = meta.forcedLieu || '';
  const mode = meta.forcedMode || '';
  const linkedinUrl = meta.forcedUrl || '';
  const reponse = forced ? meta.forcedReponse : (cat.reponse || 'A/R');

  if (DENY.has(normalize(societe))) continue;
  const match = findMatch(societe, meta);

  let action, airtableId = null;
  if (match) { airtableId = match.id; action = rankOf(reponse) > rankOf(match.reponse) ? 'update' : 'skip'; }
  else if (societeReliable && normalize(societe).length >= 2) { action = 'create'; }
  else { action = 'review'; }

  out.push({ json: {
    action, airtableId, societe, poste, reponse, lieu, mode, linkedinUrl,
    subject: meta.subject, fromRaw: meta.fromRaw, date: toIso(meta.date),
    note: bob.justification || '',
    gmailLink: meta.emailId ? `https://mail.google.com/mail/u/0/#all/${meta.emailId}` : '',
    domain: meta.domain, emailId: meta.emailId,
    confidence: bob.confiance || 'low',
    forced, existingReponse: match ? match.reponse : null,
  }});
}

const best = new Map();
const reviews = [];
for (const o of out) {
  if (o.json.action === 'review') { reviews.push(o); continue; }
  const k = (o.json.action === 'create') ? ('soc:' + normalize(o.json.societe)) : ('id:' + o.json.airtableId);
  const prev = best.get(k);
  if (!prev || rankOf(o.json.reponse) > rankOf(prev.json.reponse)) best.set(k, o);
}
return [...best.values(), ...reviews];

// Nœud "Prépa triage Veille" (Code, runOnceForAllItems)
// (Étage de triage grossier supprimé le 27/06/2026 — le scoring précis le remplace.)
// Collecte les cartes d'offres veille du jour ; la dédup + le shaping se font
// dans "Parser triage Veille". Sort un unique item { cards }.
const cards = $input.all().map((it) => it.json);
return [{ json: { cards, count: cards.length } }];

// Nœud "Parser triage Veille" (Code, runOnceForAllItems)
// (Étage de triage grossier supprimé le 27/06/2026.) Déduplique les offres par jobId
// (même offre vue dans plusieurs alertes le même jour) et formate chaque carte
// pour l'écriture Airtable. Plus d'appel Claude de pré-classement ni de champs de triage.
const src = $('Prépa triage Veille').first().json;
const cards = src.cards || [];
const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };
const seen = new Set();
const out = [];
for (const c of cards) {
  if (c.jobId && seen.has(c.jobId)) continue;
  if (c.jobId) seen.add(c.jobId);
  out.push({ json: {
    jobId: c.jobId, employeur: c.employeur, poste: c.poste, lieu: c.lieu,
    mode: c.mode, url: c.url, alertName: c.alertName, date: toIso(c.date),
    easyApply: c.easyApply || false,
  }});
}
return out;

// Nœud n8n "Veille décider" (Code, runOnceForAllItems)
// Décide create vs update pour chaque carte, SANS dépendre du pairedItem.
const existing = {};
for (const it of $('Chercher Veille').all()) {
  const j = it.json || {};
  if (j.id && j.jobId != null) existing[String(j.jobId)] = j.id;
}
// Garde-fou : offres déjà recopiées dans Candidatures ("Je postule") -> ne pas recréer
// dans la veille si une future alerte les fait réapparaître (jobId extrait de l'URL).
const applied = new Set();
for (const it of $('Lister Candidatures (URL)').all()) {
  const j = it.json || {};
  const url = j.URL || j.url || '';
  const m = String(url).match(/jobs\/view\/(\d+)/i);
  if (m) applied.add(m[1]);
}

return $('Parser triage Veille').all()
  .map((it) => it.json)
  .filter((c) => !(c.jobId && applied.has(String(c.jobId))))
  .map((c) => {
    const airtableId = existing[String(c.jobId)] || null;
    return { json: { ...c, action: airtableId ? 'update' : 'create', airtableId } };
  });

// Nœud "Filtrer à enrichir" (Code, runOnceForAllItems)
// (Pré-filtre grossier supprimé le 27/06/2026 : on score TOUTES les offres.)
// On enrichit toute offre pas encore notée (Note rôle vide).
return $input.all()
  .map(it => it.json)
  .filter(r => {
    const note = r['Note rôle'];
    return !(note && String(note).trim());
  })
  .map(r => ({ json: {
    id: r.id, jobId: r.jobId, poste: r.Poste, employeur: r.Employeur,
    lieu: r.Lieu, url: r.URL,
    easyApplyFromAirtable: r['Easy Apply'] || false
  }}));

const rec = $('Filtrer à enrichir').item.json;
const html = ($json && ($json.data || $json.body)) || '';
const clean = s => s
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim();
let desc = '';
const i = html.indexOf('show-more-less-html__markup');
if (i >= 0) {
  let chunk = html.slice(i, i + 14000).replace(/show-more-less-html__markup[^>]*>/, '');
  const cut = chunk.search(/show-more-less__button|<\/section>/);
  if (cut > 0) chunk = chunk.slice(0, cut);
  desc = clean(chunk);
}
const crit = [];
const re = /job-criteria-subheader[^>]*>([\s\S]*?)<\/h3>[\s\S]*?job-criteria-text[^>]*>([\s\S]*?)<\/span>/g;
let m;
while ((m = re.exec(html))) crit.push(clean(m[1]) + ': ' + clean(m[2]));

// Extract mode from criteria (e.g. "Télétravail: À distance")
const cleanModeLocal = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};
let modeFromJd = '';
for (const c of crit) {
  if (/télétravail|remote|workplace|travail.à.distance/i.test(c)) {
    const parts = c.split(':');
    if (parts.length > 1) modeFromJd = cleanModeLocal(parts.slice(1).join(':'));
    break;
  }
}
// Detect Easy Apply from page HTML
// Easy Apply: detect in JD HTML OR fallback on jobalert value already in Airtable
const easyApply = /candidature simplifi\u00e9e|easy apply/i.test(html) || !!rec.easyApplyFromAirtable;
return { json: { ...rec, descText: desc, criteres: crit.join(' | '), ok: desc.length > 200, modeFromJd, easyApply } };

const PROFIL = `Profil candidat : consultant senior independant, 25 ans d'experience, 100% assurance & finance. Cherche mission freelance/contract/interim (CDI senior finance possible), full remote ou hybride privilegie, TJM >= 800 EUR/j. Ouvert a l'international en remote (EMEA, Amerique du Nord, APAC).`;
const r = $json;
const prompt = `${PROFIL}

Voici une offre d'emploi. Redige DEUX notes courtes en francais, factuelles, pour aider ce candidat a decider de postuler.

OFFRE : ${r.poste} — ${r.employeur} — ${r.lieu || 'lieu n.c.'}
CRITERES LINKEDIN : ${r.criteres || 'n.c.'}
DESCRIPTION :
${(r.descText || '').slice(0, 6000)}

Reponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"note_role":"3 a 5 phrases : de quoi parle le poste, missions cles, seniorite, et en quoi il matche ou non le profil sur le FOND du role","note_criteres":"3 a 5 puces separees par des retours a la ligne, chaque ligne prefixee '- ' : pour chaque critere cle du recruteur (seniorite, type de contrat, secteur, competences, langue, localisation/remote) indique match ou ecart vs le profil","mode":"valeur parmi : A distance, Hybride, Sur site — ou null si non mentionne dans l offre"}`;
return { json: { prompt, id: r.id, jobId: r.jobId, modeFromJd: r.modeFromJd || '', easyApply: !!r.easyApply } };

const rec = $('Prépa prompt notes').item.json;
let role = '', crit = '', modeFromNotes = '';
try {
  const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { const o = JSON.parse(m[0]); role = o.note_role || ''; crit = o.note_criteres || ''; modeFromNotes = o.mode || ''; }
} catch (e) { /* laisse vide -> retente au prochain run */ }
if (!role && !crit) return null;
return { json: { id: rec.id, noteRole: role, noteCriteres: crit, modeFromNotes, modeFromJd: rec.modeFromJd || '', easyApply: !!rec.easyApply } };

// Parser score — extrait JSON de la réponse Claude
const upstream = $('Prépa prompt scoring').item.json;
const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';

let score = null, signaux = [], justification = '';
try {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) {
    const o = JSON.parse(m[0]);
    const raw = typeof o.score === 'number' ? o.score : parseInt(o.score, 10);
    score = isNaN(raw) ? null : Math.min(100, Math.max(0, raw));
    signaux = Array.isArray(o.signaux) ? o.signaux : [];
    justification = o.justification || '';
  }
} catch (e) { /* score reste null, sera ignoré par Écrire notes */ }

return { json: {
  id: upstream.id,
  noteRole: upstream.noteRole,
  noteCriteres: upstream.noteCriteres,
  modeFromNotes: upstream.modeFromNotes || '',
  modeFromJd: upstream.modeFromJd || '',
  // Préparer dossier = règle Score >= 35 (remplace l ancien pré-classement grossier, 27/06/2026).
  // score null (scoring échoué/crédits) -> pas de préparation auto (fail-safe).
  preparer: (score !== null && score >= 35),
  postule: (score !== null && score >= 35 && !!upstream.easyApply),
  easyApply: !!upstream.easyApply,
  score,
  scoreSignaux: signaux.join(' | '),
  scoreJustification: justification
}};

// Nœud "Prépa Triage BOB" (Code, runOnceForAllItems)
// Port n8n de l'agent BOB (triage 5 catégories). Reçoit TOUTE la sortie de
// "Filtrer & préparer" (kind:'veille' + kind:'candidature'). Les offres LinkedIn
// (veille) sont pré-classées "Proposition de mission" sans LLM. Les emails de
// candidature sont regroupés en UN seul prompt (1 appel Claude pour tous, comme
// l'agent BOB d'origine et comme "Prépa triage Veille") -> robuste au rate-limit.
// Sort un unique item { prompt, candEmails, veilleRecords } consommé par l'appel
// Claude puis par "Parser Triage BOB".

const all = $input.all().map((it) => it.json);
if (all.length === 0) return [];

const veilleRecords = [];
const candEmails = [];
for (const it of all) {
  if (it.kind === 'veille') {
    veilleRecords.push({
      id_email: 'li-' + (it.jobId || ''),
      sujet: it.poste || '',
      expediteur: it.employeur || '',
      categorie: 'Proposition de mission',
      societe: it.employeur || '',
      poste: it.poste || '',
      confiance: 'Haute',
      justification: 'Offre diffusée par une alerte LinkedIn' + (it.alertName ? ' (' + it.alertName + ')' : '') + '.',
      lieu: it.lieu || '',
      url: it.url || '',
      mode: it.mode || '',
    });
  } else {
    candEmails.push({
      id_email: it.emailId || it.customId || '',
      emailUrl: it.emailId ? 'https://mail.google.com/mail/u/0/#all/' + it.emailId : '',
      sujet: it.subject || '',
      expediteur: it.fromRaw || '',
      bodyClean: it.bodyClean || it.snippet || '',
    });
  }
}

const SYSTEM = `Tu es BOB, l'agent de Xavier Robitaille. Ton rôle : trier les emails liés à sa recherche de mission de conseil.
Pour CHAQUE email, attribue EXACTEMENT UNE catégorie :
- "Proposition de mission" : un recruteur/client propose une mission ou un poste précis.
- "Accusé de réception" : confirmation (souvent automatique) qu'une candidature a bien été reçue/envoyée, SANS décision.
- "Réponse positive" : intérêt, demande d'entretien/échange/disponibilités, suite favorable.
- "Refus" : candidature non retenue (« ne donnerons pas suite », « pas retenu », « unfortunately »).
- "Autre/non-pertinent" : newsletter, alerte non sollicitée, authentification/code, bienvenue/création de compte, invitation à une conférence/webinaire, notif bancaire, spam — tout ce qui n'est pas lié à une candidature précise.
Extrais la société (l'entreprise qui recrute, jamais l'ATS/plateforme : ignore LinkedIn, Welcome to the Jungle, Greenhouse, Lever, Workday) et le poste quand ils sont identifiables, sinon laisse vide.
Un accusé de réception n'est ni un refus ni une réponse positive. En cas de doute entre les trois (si c'est bien du recrutement) → "Accusé de réception".`;

const lignes = candEmails.map((e, i) =>
  `### Email ${i + 1}\nExpéditeur : ${e.expediteur}\nSujet : ${e.sujet}\nCorps : ${String(e.bodyClean || '').slice(0, 1500)}`
).join('\n\n');

const prompt = `${SYSTEM}\n\nClasse CHAQUE email ci-dessous. Réponds UNIQUEMENT par un tableau JSON, un objet par email DANS L'ORDRE, sans aucun texte autour :\n[{"i":1,"categorie":"Proposition de mission|Accusé de réception|Réponse positive|Refus|Autre/non-pertinent","societe":"... ou ''","poste":"... ou ''","confiance":"Haute|Moyenne|Basse","justification":"<=1 phrase en français"}]\n\nEMAILS :\n${lignes}`;

return [{ json: { prompt, candEmails, veilleRecords, candCount: candEmails.length } }];

// Nœud "Parser Triage BOB" (Code, runOnceForAllItems)
// Rattache la classification Claude à chaque email de candidature (par index),
// tolérant à une réponse tronquée. Y ajoute les offres veille pré-classées.
// Si l'appel Claude a échoué (onError:continueRegularOutput -> pas de .content),
// on N'ÉCRIT PAS les candidatures (évite de tout classer "Autre") : seules les
// offres veille sont écrites, les candidatures repasseront au run suivant
// (fenêtre 24h glissante).

const src = $('Prépa Triage BOB').first().json;
const candEmails = src.candEmails || [];
const veilleRecords = src.veilleRecords || [];

const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
const claudeOk = !!txt;

const byI = {};
const objs = txt.match(/\{[^{}]*\}/g) || [];
for (const frag of objs) {
  try { const o = JSON.parse(frag); if (o && o.i != null) byI[Number(o.i)] = o; } catch (e) {}
}

const validCat = ['Proposition de mission', 'Accusé de réception', 'Réponse positive', 'Refus', 'Autre/non-pertinent'];
const validConf = ['Haute', 'Moyenne', 'Basse'];

const out = [];
for (const v of veilleRecords) out.push({ json: v });

if (claudeOk) {
  candEmails.forEach((e, idx) => {
    const o = byI[idx + 1];
    if (!o) return; // pas de classif (réponse tronquée) -> réécrit au prochain run
    const categorie = validCat.includes(o.categorie) ? o.categorie : 'Autre/non-pertinent';
    const confiance = validConf.includes(o.confiance) ? o.confiance : 'Basse';
    out.push({ json: {
      id_email: e.id_email,
      sujet: e.sujet,
      expediteur: e.expediteur,
      categorie,
      societe: o.societe || '',
      poste: o.poste || '',
      confiance,
      justification: o.justification || '',
      lieu: '', url: '', mode: '',
      emailUrl: e.emailUrl || '',
    }});
  });
}

return out;
